<script setup lang="ts">
import { RouterLink } from 'vue-router';
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { defaultFeishuRule, type FeishuWorkspace, type FeishuBot, type FeishuBotDraft, type FeishuRuleDraft, type NotificationRule, type FeishuMessage, type FeishuDelivery } from '../../../../shared/src/feishu';
import { isProjectManager } from '../../../../shared/src/permissions';
import { useAuthStore } from '../../stores/auth';
import { PlanningError } from '../../api/planning';
import { fetchFeishu, saveFeishu, previewFeishu, fetchFeishuDeliveries, fetchFeishuDelivery, recoverFeishuDelivery } from '../../api/feishu';
import FeishuMessagePreview from './FeishuMessagePreview.vue';
import '../tasks/task-drawer.css';
import './feishu.css';
const props=defineProps<{projectId:string;actorId:string}>();
const emit=defineEmits<{notify:[message:string];revoked:[]}>();
const auth=useAuthStore(), workspace=ref<FeishuWorkspace>(), tab=ref('rules'), loading=ref(false), busy=ref(false), error=ref(''), notice=ref(''), stale=ref(false), denied=ref(false);
const manager=computed(()=>!denied.value && (auth.session?.legacyDemo||!!auth.actorForProject(props.projectId))&&(auth.user?.systemRole==='admin'||workspace.value?.actors.some(a=>a.id===props.actorId&&isProjectManager(a.role))));
const writable=computed(()=>manager.value&&workspace.value?.available&&!busy.value&&!loading.value&&!stale.value);
const modal=ref<''|'bot'|'rule'|'preferences'|'action'|'delivery'>(''),dialog=ref<HTMLDialogElement>(), editingId=ref(''), baseline=ref(''), confirmLeave=ref(false), stage=ref<'edit'|'preview'>('edit'), preview=ref<FeishuMessage>();
const bot=ref<FeishuBotDraft>({name:'',groupName:'',webhook:'',signatureEnabled:true,keyword:''});
const rule=ref<FeishuRuleDraft>(defaultFeishuRule());
const preferences=reactive({quietEnabled:true,quietStart:'20:00',quietEnd:'09:00'});
const compact=ref(window.matchMedia('(max-width: 640px)').matches);
const sampleMessage=computed<FeishuMessage>(()=>({title:rule.value.name||'通知卡片示例',projectName:workspace.value?.project.name||'当前项目',lines:['示例：符合条件的事项、负责人及状态将在此展示。','保存草稿不会发送；启用后只按规则发送真实项目数据。'],total:0,url:null,linkLabel:'',mentionAll:rule.value.mentionAll,generatedAt:new Date().toISOString(),isDemo:true}));
const action=ref({path:'',title:'',description:''});
const detail=ref<FeishuDelivery>(), deliveryAction=ref<''|'retry'|'received'>('');
const statusNames:Record<string,string>={draft:'草稿',enabled:'已启用',paused:'已暂停',archived:'已归档',pending:'待发送',sending:'发送中',accepted:'飞书已接收',failed:'发送失败',unknown:'结果待核实',cancelled:'已取消',skipped:'已跳过',missed:'错过发送时间'};
const riskLabels:Record<string,string>={low:'低',medium:'中',high:'高',critical:'严重'},alertLabels:Record<string,string>={overdue:'任务逾期',dependency_blocked:'依赖阻塞',blocked_2_days:'持续阻塞',milestone_forecast_late:'里程碑预计延期',capacity_overload:'容量超负荷',commitment_incomplete:'交付承诺未完整'};
const ruleQuery=ref(''),ruleStatus=ref(''),ruleTemplate=ref(''),ruleBot=ref('');
const displayedRules=computed(()=>(workspace.value?.rules||[]).filter(r=>(!ruleStatus.value||r.status===ruleStatus.value)&&r.name.includes(ruleQuery.value)&&(!ruleTemplate.value||r.template===ruleTemplate.value)&&(!ruleBot.value||r.botIds.includes(ruleBot.value))));
const template=computed(()=>workspace.value?.templates.find(t=>t.id===rule.value.template));
const filter=reactive({status:'',botId:'',ruleId:'',days:7,page:1,pageSize:20}),deliveries=ref<FeishuDelivery[]>([]),total=ref(0),recordsLoading=ref(false);
const snapshot=()=>JSON.stringify(modal.value==='bot'?bot.value:modal.value==='rule'?rule.value:modal.value==='preferences'?preferences:null);
const dirty=computed(()=>!!modal.value&&['bot','rule','preferences'].includes(modal.value)&&snapshot()!==baseline.value);
const compactMedia=window.matchMedia('(max-width: 640px)');const resize=()=>{compact.value=compactMedia.matches;};
let disposed=false,pendingNavigation:((allow:boolean)=>void)|undefined,signature='',requestKey='',recordsRequest=0;
let pendingEnable:{id:string;fingerprint:string;body:{expectedVersion:number;confirmed:true};key:string}|undefined;
const ruleFingerprint=(value:FeishuRuleDraft)=>JSON.stringify(Object.fromEntries(Object.keys(defaultFeishuRule()).map(key=>[key,value[key as keyof FeishuRuleDraft]])));
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
const time=(value:string|null)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—';
async function load(){if(loading.value)return;loading.value=true;try{const next=await fetchFeishu(props.projectId,props.actorId);if(disposed)return;workspace.value=next;if(pendingEnable){const saved=next.rules.find(r=>r.id===pendingEnable!.id);if(saved?.status==='enabled'&&ruleFingerprint(saved)===pendingEnable.fingerprint){pendingEnable=undefined;finishClose();emit('notify','已核实规则启用成功，不重复保存或发送。');}else pendingEnable=undefined;}if(modal.value==='delivery'&&detail.value){detail.value=await fetchFeishuDelivery(props.projectId,detail.value.id,props.actorId);deliveryAction.value='';}denied.value=false;stale.value=false;stage.value='edit';signature='';error.value='';notice.value=modal.value?'已读取最新配置，草稿保留，请重新核对。':'';}catch(e){handleError(e);}finally{loading.value=false;}}
function handleError(e:unknown){error.value=e instanceof Error?e.message:'操作失败，请重试。';if(e instanceof PlanningError&&[403,409].includes(e.status)){stale.value=true;stage.value='edit';error.value+=' 草稿已保留，请刷新配置与权限后重新核对。';if(e.status===403){denied.value=true;void auth.refreshForRecovery();emit('revoked');}}}
async function open(kind:typeof modal.value){error.value='';notice.value='';stage.value='edit';preview.value=undefined;confirmLeave.value=false;modal.value=kind;baseline.value=snapshot();signature='';await nextTick();dialog.value?.showModal();}
function openBot(value?:FeishuBot){editingId.value=value?.id||'';bot.value=value?{name:value.name,groupName:value.groupName,signatureEnabled:value.signatureEnabled,keyword:value.keyword,webhook:'',secret:''}:{name:'',groupName:'',webhook:'',signatureEnabled:true,secret:'',keyword:''};void open('bot');}
function openRule(value?:NotificationRule){pendingEnable=undefined;editingId.value=value?.id||'';rule.value=value?Object.fromEntries(Object.keys(defaultFeishuRule()).map(key=>[key,clone(value[key as keyof FeishuRuleDraft])])) as unknown as FeishuRuleDraft:defaultFeishuRule();void open('rule');}
function changeTemplate(){const previous=rule.value;rule.value={...defaultFeishuRule(previous.template),botIds:previous.botIds};}
function openPreferences(){Object.assign(preferences,workspace.value!.preferences);void open('preferences');}
function askAction(path:string,title:string,description:string){action.value={path,title,description};void open('action');}
function revealLeave(){confirmLeave.value=true;void nextTick(()=>{const panel=dialog.value?.querySelector<HTMLElement>('.td-leave-panel');panel?.scrollIntoView({block:'start'});panel?.querySelector('button')?.focus();});}
function close(){if(busy.value||loading.value)return;if(dirty.value){revealLeave();return;}finishClose();}
function finishClose(){pendingEnable=undefined;dialog.value?.close();modal.value='';detail.value=undefined;deliveryAction.value='';confirmLeave.value=false;}
function discard(){confirmLeave.value=false;if(pendingNavigation){pendingNavigation(true);pendingNavigation=undefined;}finishClose();}
function keep(){confirmLeave.value=false;pendingNavigation?.(false);pendingNavigation=undefined;}
function confirmNavigation():Promise<boolean>{if(busy.value||loading.value)return Promise.resolve(false);if(!dirty.value)return Promise.resolve(true);revealLeave();return new Promise(resolve=>{pendingNavigation?.(false);pendingNavigation=resolve;});}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue='';}}
function keyFor(path:string,body:unknown){const next=JSON.stringify({path,body,actor:props.actorId,token:workspace.value?.writeToken});if(signature!==next){signature=next;requestKey=crypto.randomUUID();}return requestKey;}
async function mutate(path:string,body:unknown){const w=workspace.value!;const next=await saveFeishu(w,props.actorId,path,body,keyFor(path,body));if(!disposed)workspace.value=next;return next;}
async function saveBot(){if(!writable.value)return;busy.value=true;error.value='';try{const draft={...bot.value};if(!draft.webhook)delete draft.webhook;if(!draft.secret)delete draft.secret;await mutate(`/bots${editingId.value?`/${encodeURIComponent(editingId.value)}`:''}`,{expectedVersion:workspace.value!.version,bot:draft});finishClose();emit('notify','机器人已保存。请明确发送测试并核对目标群。');}catch(e){handleError(e);}finally{busy.value=false;}}
async function reviewRule(){if(!writable.value)return;if(!rule.value.name.trim()||!rule.value.botIds.length){error.value='请填写规则名称并选择至少一个目标机器人。';return;}busy.value=true;error.value='';try{preview.value=await previewFeishu(workspace.value!,props.actorId,clone(rule.value));stage.value='preview';await nextTick();dialog.value?.querySelector('.fs-confirmation')?.scrollIntoView({block:'start'});}catch(e){handleError(e);}finally{busy.value=false;}}
async function saveRule(enable:boolean){
 if(!writable.value||enable&&stage.value!=='preview')return;
 busy.value=true;error.value='';
 try{
  const fingerprint=ruleFingerprint(rule.value);
  if(!enable||!pendingEnable||pendingEnable.fingerprint!==fingerprint){
   pendingEnable=undefined;
   const beforeIds=new Set(workspace.value!.rules.map(r=>r.id));
   const next=await mutate(`/rules${editingId.value?`/${encodeURIComponent(editingId.value)}`:''}`,{expectedVersion:workspace.value!.version,rule:clone(rule.value)});
   if(!editingId.value)editingId.value=next.rules.find(r=>!beforeIds.has(r.id))?.id||'';
   baseline.value=snapshot();
   if(enable){if(!editingId.value)throw new Error('草稿已保存，请关闭后从规则列表重新启用。');pendingEnable={id:editingId.value,fingerprint,body:{expectedVersion:next.version,confirmed:true},key:crypto.randomUUID()};}
  }
  if(enable&&pendingEnable){workspace.value=await saveFeishu(workspace.value!,props.actorId,`/rules/${encodeURIComponent(pendingEnable.id)}/enable`,pendingEnable.body,pendingEnable.key);pendingEnable=undefined;}
  finishClose();emit('notify',enable?'规则已启用，从现在起生效；不补发历史消息。':'规则草稿已保存，尚未发送。');
 }catch(e){handleError(e);if(editingId.value)notice.value='规则草稿已保存。启用结果尚未确认，重试会复用本次操作凭证，不会重复保存规则。';}
 finally{busy.value=false;}
}
async function savePreferences(){if(!writable.value)return;busy.value=true;try{await mutate('/preferences',{expectedVersion:workspace.value!.version,preferences:{quietEnabled:preferences.quietEnabled,quietStart:preferences.quietStart,quietEnd:preferences.quietEnd},confirmed:true});finishClose();emit('notify','发送偏好已保存。');}catch(e){handleError(e);}finally{busy.value=false;}}
async function executeAction(){if(!writable.value)return;busy.value=true;error.value='';try{await mutate(action.value.path,{expectedVersion:workspace.value!.version,confirmed:true});finishClose();emit('notify','操作已提交，请查看状态与发送记录。');}catch(e){handleError(e);}finally{busy.value=false;}}
async function loadDeliveries(){const request=++recordsRequest;recordsLoading.value=true;try{const result=await fetchFeishuDeliveries(props.projectId,{...filter},props.actorId);if(disposed||request!==recordsRequest)return;deliveries.value=result.items;total.value=result.total;}catch(e){if(request===recordsRequest)handleError(e);}finally{if(request===recordsRequest)recordsLoading.value=false;}}
async function openDelivery(value:FeishuDelivery){detail.value=value;deliveryAction.value='';await open('delivery');try{detail.value=await fetchFeishuDelivery(props.projectId,value.id,props.actorId);}catch(e){handleError(e);}}
async function recoverDelivery(){if(!writable.value||!detail.value||!deliveryAction.value||!['failed','unknown'].includes(detail.value.status))return;busy.value=true;error.value='';try{const path=`${detail.value.id}/${deliveryAction.value}`;detail.value=await recoverFeishuDelivery(workspace.value!,props.actorId,detail.value,deliveryAction.value,keyFor(path,{version:detail.value.version}));deliveryAction.value='';await loadDeliveries();notice.value='处理结果已留痕，请核对最新状态。';}catch(e){handleError(e);}finally{busy.value=false;}}
watch(()=>[filter.status,filter.botId,filter.ruleId,filter.days],()=>{filter.page=1;void loadDeliveries();});watch(()=>filter.page,loadDeliveries);watch(tab,value=>{if(value==='deliveries')void loadDeliveries();});watch(()=>props.actorId,()=>{if(!dirty.value)void load();else{stale.value=true;stage.value='edit';}});
onMounted(()=>{compactMedia.addEventListener('change',resize);void load();window.addEventListener('beforeunload',beforeUnload);});onBeforeUnmount(()=>{compactMedia.removeEventListener('change',resize);disposed=true;window.removeEventListener('beforeunload',beforeUnload);pendingNavigation?.(false);dialog.value?.close();});
defineExpose({confirmNavigation,hasDraft:()=>dirty.value||busy.value,refresh:load});
</script>
<template>
<section class="fs-panel settings-panel" aria-label="通知与集成">
 <header class="settings-panel-heading"><div><h2>通知与集成</h2><p>当前项目独立配置 · 飞书群通知 · Asia/Shanghai</p></div><button class="button" :disabled="loading||busy||!!modal" @click="load">刷新集成</button></header>
 <p v-if="loading&&!workspace" class="settings-empty" role="status">正在读取飞书通知配置…</p>
 <div v-if="error&&!modal" class="settings-error" role="alert">{{ error }}<button class="button" :disabled="loading" @click="load">重新加载</button></div>
 <template v-if="workspace"><p v-if="!workspace.available" class="settings-notice fs-inset">飞书通知尚未就绪：{{ workspace.unavailableReason||'请由系统管理员在系统设置配置或恢复飞书主密钥。' }} 已有项目功能和站内通知仍可使用。<RouterLink v-if="auth.user?.systemRole==='admin'" class="settings-link" :to="{name:'system-settings',query:{returnTo:`/projects/${encodeURIComponent(projectId)}/settings?tab=integrations`}}">前往系统设置</RouterLink><span v-else> 请联系系统管理员。</span></p><p v-if="!manager" class="settings-notice fs-inset">当前账号没有飞书集成管理权限，请联系项目负责人。</p><p v-if="!workspace.publicBaseUrl" class="settings-muted fs-inset">尚未配置系统访问地址，通知卡片将省略跳转按钮。</p>
 <nav class="fs-tabs" aria-label="飞书集成分类"><button v-for="item in [{id:'rules',label:'通知规则'},{id:'bots',label:'飞书机器人'},{id:'deliveries',label:'发送记录'}]" :key="item.id" :aria-pressed="tab===item.id" @click="tab=item.id">{{ item.label }}</button></nav>
 <section v-if="tab==='rules'"><div class="fs-toolbar"><label>搜索规则<input v-model="ruleQuery" placeholder="规则名称"/></label><label>规则状态<select v-model="ruleStatus"><option value="">全部状态</option><option v-for="s in ['draft','enabled','paused','archived']" :key="s" :value="s">{{ statusNames[s] }}</option></select></label><label>规则模板<select v-model="ruleTemplate" aria-label="规则模板筛选"><option value="">全部模板</option><option v-for="t in workspace.templates" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><label>目标机器人<select v-model="ruleBot" aria-label="规则目标机器人筛选"><option value="">全部机器人</option><option v-for="b in workspace.bots" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><button class="button" :disabled="!writable" @click="openPreferences">发送偏好</button><button class="button primary" :disabled="!writable" @click="openRule()">＋ 新建规则</button></div>
 <article v-for="item in displayedRules" :key="item.id" class="fs-row" data-testid="feishu-rule"><div><strong>{{ item.name }}</strong><span class="fs-badge">{{ statusNames[item.status] }}</span><p>{{ workspace.templates.find(t=>t.id===item.template)?.name }} · {{ item.botIds.length }} 个目标群 · {{ item.mentionAll?'@所有人':'不@所有人' }}</p><small>{{ item.status==='enabled'&&!item.template.endsWith('_event')&&item.schedule.mode==='workdays'&&!workspace.calendarConfirmed&&!item.nextRunAt ? '日历未确认，暂不调度' : `下次计划：${time(item.nextRunAt)}` }}</small></div><div class="fs-actions"><button class="settings-link" :disabled="!writable||item.status==='archived'" @click="openRule(item)">{{ item.status==='enabled'?'编辑':'编辑／启用' }}</button><button v-if="item.status==='enabled'" class="settings-link" :disabled="!writable" @click="askAction(`/rules/${item.id}/pause`,'暂停规则',`暂停「${item.name}」，取消尚未发送的消息；已发出的请求无法撤回。`) ">暂停</button><button class="settings-link" :disabled="!writable" @click="askAction(`/rules/${item.id}/copy`,'复制为草稿',`复制「${item.name}」为新草稿，不会自动发送。`)">复制</button><button v-if="item.status!=='archived'" class="settings-link" :disabled="!writable" @click="askAction(`/rules/${item.id}/archive`,'归档规则',`归档「${item.name}」并取消待发消息，发送记录保留。`)">归档</button></div></article><p v-if="!displayedRules.length" class="settings-empty">暂无符合条件的规则。先添加并核对飞书机器人，再新建规则。</p>
 </section>
 <section v-else-if="tab==='bots'"><div class="fs-toolbar"><p>保存凭据不会发送消息；测试成功后，请到飞书核对群名。</p><button class="button primary" :disabled="!writable" @click="openBot()">＋ 添加机器人</button></div><article v-for="item in workspace.bots" :key="item.id" class="fs-row" data-testid="feishu-bot"><div><strong>{{ item.name }}</strong><span class="fs-badge">{{ !item.enabled?'已暂停':!item.testedAt?'待测试':!item.confirmedAt?'待核对目标群':'已启用' }}</span><p>目标群：{{ item.groupName }} · {{ item.maskedWebhook }}</p><small>测试：{{ time(item.testedAt) }} · 群核对：{{ time(item.confirmedAt) }}</small><p v-if="!item.enabled">机器人已暂停，请先启用，再发送测试或恢复规则。</p><p v-if="item.lastError" class="fs-failure">{{ item.lastError }}</p></div><div class="fs-actions"><button class="settings-link" :disabled="!writable" @click="openBot(item)">编辑</button><button class="settings-link" :disabled="!writable||!item.enabled" @click="askAction(`/bots/${item.id}/test`,'发送测试卡片',`将向「${item.groupName}」发送一张测试卡片，不包含业务数据，不@所有人。请在发送后到飞书核对实际收到的群。`)">发送测试</button><button v-if="!item.confirmedAt" class="settings-link" :disabled="!writable||!item.testedAt" @click="askAction(`/bots/${item.id}/confirm`,'核对目标群',`请确认已在飞书「${item.groupName}」看到此机器人的测试卡片。飞书接收成功并不能代替人工核对群。`)">核对目标群</button><button class="settings-link" :disabled="!writable" @click="askAction(`/bots/${item.id}/${item.enabled?'pause':'enable'}`,item.enabled?'暂停机器人':'启用机器人',item.enabled?`暂停「${item.groupName}」机器人并取消待发消息，已发出请求无法撤回。`:`启用「${item.groupName}」机器人，不补发历史消息。`)">{{ item.enabled?'暂停':'启用' }}</button></div></article><p v-if="!workspace.bots.length" class="settings-empty">尚未添加飞书机器人。添加群 Webhook 后，发送测试并核对目标群。</p></section>
 <section v-else><div class="fs-toolbar"><label>发送状态<select v-model="filter.status"><option value="">全部状态</option><option v-for="s in ['pending','sending','accepted','failed','unknown','cancelled','skipped','missed']" :key="s" :value="s">{{ statusNames[s] }}</option></select></label><label>目标机器人<select v-model="filter.botId"><option value="">全部机器人</option><option v-for="b in workspace.bots" :key="b.id" :value="b.id">{{ b.name }}</option></select></label><label>通知规则<select v-model="filter.ruleId"><option value="">全部规则</option><option v-for="r in workspace.rules" :key="r.id" :value="r.id">{{ r.name }}</option></select></label><label>时间范围<select v-model="filter.days"><option :value="1">最近 1 天</option><option :value="7">最近 7 天</option><option :value="30">最近 30 天</option><option :value="90">最近 90 天</option></select></label><button class="button" :disabled="recordsLoading" @click="loadDeliveries">刷新记录</button></div><p v-if="recordsLoading" class="settings-empty" role="status">正在读取发送记录…</p><article v-for="item in deliveries" :key="item.id" class="fs-row" data-testid="feishu-delivery"><div><strong>{{ item.ruleName }}</strong><span class="fs-badge">{{ statusNames[item.status] }}</span><p>{{ item.botName }} → {{ item.groupName }} · {{ time(item.createdAt) }}</p><p v-if="item.error">{{ item.error }}</p></div><button class="settings-link" @click="openDelivery(item)">详情</button></article><p v-if="!recordsLoading&&!deliveries.length" class="settings-empty">当前筛选范围内没有发送记录。可调整筛选，或在机器人页明确发送测试。</p><footer class="fs-pagination"><button class="button" :disabled="recordsLoading||filter.page<=1" @click="filter.page--">上一页</button><span>第 {{ filter.page }} 页 · 共 {{ total }} 条</span><button class="button" :disabled="recordsLoading||filter.page*filter.pageSize>=total" @click="filter.page++">下一页</button></footer></section>
 <details class="fs-audit"><summary>集成操作记录 · {{ workspace.audit.length }} 条</summary><p v-for="a in workspace.audit" :key="a.id">{{ time(a.at) }} · {{ a.actor }} · {{ a.action }}</p><p v-if="!workspace.audit.length">尚无配置变更，保存后的操作会留痕。</p></details>
 </template>
 <dialog v-if="modal" ref="dialog" class="task-drawer fs-drawer" aria-labelledby="feishu-dialog-title" @cancel.prevent="close"><div class="td-shell"><header class="td-header"><div class="td-header-row"><span class="td-reference">{{ workspace?.project.name }} · 飞书通知</span><button class="td-icon-button" aria-label="关闭飞书编辑" :disabled="busy||loading" @click="close">✕</button></div><h2 id="feishu-dialog-title">{{ modal==='bot'?(editingId?'编辑机器人':'添加机器人'):modal==='rule'?(editingId?'编辑通知规则':'新建通知规则'):modal==='preferences'?'发送偏好':modal==='delivery'?'发送详情':action.title }}</h2><p class="td-stream">{{ workspace?.actors.find(a=>a.id===actorId)?.name||auth.user?.name }} · 配置 V{{ workspace?.version }}</p></header>
 <div class="td-body"><section v-if="confirmLeave" class="td-leave-panel" role="alert"><h3>离开将丢弃未保存的草稿</h3><div class="fs-actions"><button class="button" @click="keep">继续编辑</button><button class="button" @click="discard">丢弃草稿并离开</button></div></section><div v-if="error" class="td-error" role="alert">{{ error }}<button v-if="stale" class="button" :disabled="loading||busy" @click="load">刷新配置并保留草稿</button></div><p v-if="notice" class="td-notice" role="status">{{ notice }}</p><p v-if="!manager" class="td-warning">当前账号已无配置权限，草稿保留。请联系负责人恢复权限后刷新。</p>
 <p v-if="modal==='bot'" class="td-notice">飞书签名密钥属于单个机器人凭据，并不是系统主密钥。机器人凭据由系统主密钥加密后自动持久化，无需另行复制。</p>
 <form v-if="modal==='bot'" id="fs-bot-form" class="td-form" @submit.prevent="saveBot"><fieldset :disabled="!writable"><label class="td-field">机器人名称<input v-model="bot.name" required maxlength="60"/></label><label class="td-field">目标群名称<input v-model="bot.groupName" required maxlength="100"/></label><label class="td-field">飞书 Webhook<input v-model="bot.webhook" aria-label="飞书 Webhook" type="password" autocomplete="new-password" :required="!editingId" placeholder="https://open.feishu.cn/open-apis/bot/v2/hook/…"/><small v-if="editingId">留空保留现有地址。修改地址会暂停关联规则，并要求重测及核对目标群。</small></label><label class="td-check"><input v-model="bot.signatureEnabled" type="checkbox"/>开启签名校验</label><label v-if="bot.signatureEnabled" class="td-field">签名密钥<input v-model="bot.secret" aria-label="签名密钥" type="password" autocomplete="new-password" :required="!editingId"/><small>编辑时留空保留已保存密钥；修改后须重新测试。</small></label><label class="td-field">关键词（可选）<input v-model="bot.keyword" maxlength="40"/><small>与飞书机器人安全设置一致，测试和业务卡片都会带上该关键词。</small></label><p class="td-notice">保存不会发送。密钥仅用于服务端发送，保存后不再显示完整凭据。</p></fieldset></form>
 <template v-if="modal==='rule'"><div class="fs-rule-workspace"><form id="fs-rule-form" class="td-form" @submit.prevent="reviewRule"><fieldset :disabled="!writable||stage==='preview'"><label class="td-field">业务模板<select aria-label="业务模板" v-model="rule.template" @change="changeTemplate"><option v-for="t in workspace?.templates" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><label class="td-field">规则名称<input v-model="rule.name" required maxlength="100"/></label><section v-if="template?.actions.length"><h3>触发动作</h3><div class="fs-checks"><label v-for="a in template.actions" :key="a.id" class="td-check"><input v-model="rule.actions" type="checkbox" :value="a.id"/>{{ a.name }}</label></div></section><label v-if="template?.category==='reminder'" class="td-field">对象范围<select v-model="rule.objectType"><option value="task">任务</option><option v-if="rule.template!=='blocked_reminder'" value="milestone">里程碑</option></select></label><div class="fs-form-grid"><label v-if="rule.template!=='plan_event'" class="td-field">工作分组（不选为全部）<select v-model="rule.workstreamIds" multiple><option v-for="w in workspace?.workstreams" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label v-if="rule.template!=='plan_event'" class="td-field">负责人（不选为全部）<select v-model="rule.ownerIds" multiple><option v-for="a in workspace?.actors.filter(actor=>actor.assignable!==false)" :key="a.id" :value="a.id">{{ a.name }}</option></select></label></div><template v-if="rule.template==='risk_event'"><label class="td-field">人工风险等级（不选为全部）<select v-model="rule.riskLevels" multiple><option value="critical">严重</option><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label><label class="td-field">自动预警类型（不选为全部）<select v-model="rule.alertTypes" multiple><option value="overdue">任务逾期</option><option value="blocked_2_days">持续阻塞</option><option value="milestone_forecast_late">里程碑预计延期</option><option value="dependency_blocked">依赖阻塞</option><option value="capacity_overload">容量超负荷</option><option value="commitment_incomplete">交付承诺未完整</option></select></label></template><label v-if="template?.category==='reminder'" class="td-field">阈值（自然日）<input v-model.number="rule.days" type="number" min="0" max="365" required/></label><template v-if="template?.category!=='event'"><div class="fs-form-grid"><label class="td-field">调度日期<select v-model="rule.schedule.mode"><option value="workdays">项目工作日（含逐日例外）</option><option value="weekdays">指定星期</option></select></label><label class="td-field">发送时间（上海）<input v-model="rule.schedule.time" type="time" required/></label></div><div v-if="rule.schedule.mode==='weekdays'" class="fs-checks"><label v-for="(label,index) in ['日','一','二','三','四','五','六']" :key="index" class="td-check"><input v-model="rule.schedule.weekdays" type="checkbox" :value="index"/>周{{ label }}</label></div><p v-if="rule.schedule.mode==='workdays'&&!workspace?.calendarConfirmed" class="td-warning">工作日历尚未确认，可以保存草稿，请先在工作日历中核对后再启用。</p><label v-if="template?.category==='report'" class="td-check"><input v-model="rule.skipEmpty" type="checkbox"/>没有事项时不发送报告</label><p v-else class="td-field-note">提醒无符合条件的事项时不发送。</p></template><label v-else class="td-field">发送节奏<select v-model="rule.deliveryMode"><option value="merged">合并 10 分钟内事件</option><option value="immediate">立即发送</option></select></label><label class="td-check"><input v-model="rule.bypassQuiet" type="checkbox"/>此规则允许突破免打扰</label><section><h3>目标机器人</h3><label v-for="b in workspace?.bots" :key="b.id" class="td-check"><input v-model="rule.botIds" type="checkbox" :value="b.id"/>{{ b.name }} · {{ b.groupName }}{{ !b.testedAt||!b.confirmedAt?'（待测试／核对）':!b.enabled?'（已暂停）':'' }}</label><p v-if="!workspace?.bots.length" class="td-warning">尚无机器人，请先关闭并添加机器人；可保留无目标的草稿。</p></section><label class="td-check"><input v-model="rule.mentionAll" type="checkbox"/>@所有人（会打扰群内全部成员）</label></fieldset></form><aside class="fs-preview-column"><details :open="!compact||stage==='preview'"><summary>消息预览 · {{ stage==='preview'?'当前数据':'示例布局' }}</summary><p class="td-field-note">{{ stage==='preview'?'已读取当前项目数据，确认前请核对目标群与规则范围。':'此处仅展示示例布局。点击“预览并确认启用”读取当前项目数据。' }}</p><FeishuMessagePreview :message="stage==='preview'&&preview?preview:sampleMessage"/></details></aside></div>
 <section v-if="stage==='preview'" class="fs-confirmation"><h3>核对后启用</h3><p>规则：{{ rule.name }} · {{ template?.name }} · {{ template?.category==='report'?'项目汇报':rule.template==='milestone_event'?'里程碑':rule.template==='risk_event'?'风险与预警':rule.template==='plan_event'?'项目计划':rule.objectType==='task'?'任务':'里程碑' }}</p><p v-if="template?.category==='event'">触发动作：{{ template.actions.filter(a=>rule.actions.includes(a.id)).map(a=>a.name).join('、') }}</p><p v-if="template?.category==='reminder'">提醒阈值：{{ rule.days }} 个自然日</p><p v-if="rule.template==='risk_event'">人工风险等级（仅用于人工风险）：{{ rule.riskLevels.length?rule.riskLevels.map(l=>riskLabels[l]||l).join('、'):'全部' }} · 自动预警类型（仅用于自动预警）：{{ rule.alertTypes.length?rule.alertTypes.map(t=>alertLabels[t]||t).join('、'):'全部' }}</p><p>目标群：{{ workspace?.bots.filter(b=>rule.botIds.includes(b.id)).map(b=>b.groupName).join('、') }}</p><p>范围：{{ rule.workstreamIds.length?workspace?.workstreams.filter(w=>rule.workstreamIds.includes(w.id)).map(w=>w.name).join('、'):'全部工作分组' }} · {{ rule.ownerIds.length?workspace?.actors.filter(a=>rule.ownerIds.includes(a.id)).map(a=>a.name).join('、'):'全部负责人' }}</p><p>{{ template?.category==='event'?(rule.deliveryMode==='merged'?'合并 10 分钟':'立即发送'):`${rule.schedule.mode==='workdays'?'项目工作日':rule.schedule.weekdays.map(d=>'周'+['日','一','二','三','四','五','六'][d]).join('、')} ${rule.schedule.time}（上海）` }} · {{ rule.bypassQuiet?'突破免打扰':'遵守免打扰' }} · {{ rule.mentionAll?'@所有人':'不@所有人' }}</p><p>确认后生效，恢复不补历史消息。发送前再次校验规则和目标群状态。</p><button class="settings-link" :disabled="busy" @click="stage='edit'">返回修改</button></section></template>
 <form v-if="modal==='preferences'" id="fs-preferences-form" class="td-form" @submit.prevent="savePreferences"><fieldset :disabled="!writable"><label class="td-check"><input v-model="preferences.quietEnabled" type="checkbox"/>启用免打扰时段</label><div class="fs-form-grid"><label class="td-field">开始时间<input v-model="preferences.quietStart" type="time" required/></label><label class="td-field">结束时间<input v-model="preferences.quietEnd" type="time" required/></label></div><p class="td-notice">仅当前项目 · Asia/Shanghai。普通规则在免打扰结束后发送；标记突破免打扰的规则仍会发送。确认保存后生效并保留操作记录。</p></fieldset></form>
 <section v-if="modal==='action'" class="fs-confirmation"><h3>{{ action.title }}</h3><p>{{ action.description }}</p><p>操作人及时间会保留在集成记录中。</p></section>
 <section v-if="modal==='delivery'&&detail"><p><span class="fs-badge">{{ statusNames[detail.status] }}</span>{{ detail.botName }} → {{ detail.groupName }}</p><p>计划：{{ time(detail.dueAt) }} · 完成：{{ time(detail.finishedAt) }}</p><p v-if="detail.error" class="td-error">{{ detail.error }}</p><p v-if="detail.status==='unknown'" class="td-warning">请求结果无法确认，不会自动重发。请先到目标群核对；重发可能产生重复消息。</p><p v-if="detail.status==='sending'" class="td-notice">请求发送中，请稍后刷新记录；已发出的请求无法撤回。</p><FeishuMessagePreview :message="detail.message" historical/><h3>发送尝试</h3><p v-for="(attempt,index) in detail.attempts" :key="index">{{ time(attempt.at) }} · {{ attempt.outcome }} · {{ attempt.message }}</p><h3>人工处理记录</h3><p v-for="(a,index) in detail.audit" :key="index">{{ time(a.at) }} · {{ a.actor }} · {{ a.action }}</p><p v-if="!detail.audit.length">尚无人工处理记录。</p><div v-if="!deliveryAction" class="fs-actions"><button v-if="detail.status==='failed'||detail.status==='unknown'" class="button" :disabled="!writable" @click="deliveryAction='retry'">核对后重新发送</button><button v-if="detail.status==='unknown'" class="button" :disabled="!writable" @click="deliveryAction='received'">标记已收到</button></div><section v-if="deliveryAction" class="fs-confirmation"><h3>{{ deliveryAction==='retry'?'确认重新发送':'确认已在目标群收到' }}</h3><p>目标群：{{ detail.groupName }} · 消息：{{ detail.message.title }}</p><p>{{ deliveryAction==='retry'?'再次发送可能产生重复消息，请先核对群记录；系统会再次校验有效规则。':'此操作只记录人工核对结果，不会发送消息。' }}</p><div class="fs-actions"><button class="button" :disabled="busy" @click="deliveryAction=''">取消处理</button><button class="button primary" :disabled="!writable" @click="recoverDelivery">{{ busy?'处理中…':deliveryAction==='retry'?'确认重发':'确认已收到' }}</button></div></section></section>
 </div><footer class="td-footer"><button class="button" :disabled="busy||loading" @click="close">{{ modal==='delivery'?'关闭':'取消' }}</button><template v-if="modal==='bot'"><button class="button primary" form="fs-bot-form" :disabled="!writable">{{ busy?'正在保存…':'保存机器人' }}</button></template><template v-else-if="modal==='rule'"><button class="button" :disabled="!writable" @click="saveRule(false)">保存草稿</button><button v-if="stage==='edit'" class="button primary" form="fs-rule-form" :disabled="!writable">{{ busy?'正在预览…':'预览并确认启用' }}</button><button v-else class="button primary" :disabled="!writable||rule.schedule.mode==='workdays'&&template?.category!=='event'&&!workspace?.calendarConfirmed" @click="saveRule(true)">{{ busy?'正在启用…':'确认启用规则' }}</button></template><button v-else-if="modal==='preferences'" class="button primary" form="fs-preferences-form" :disabled="!writable">{{ busy?'正在保存…':'确认保存偏好' }}</button><button v-else-if="modal==='action'" class="button primary" :disabled="!writable" @click="executeAction">{{ busy?'处理中…':`确认${action.title}` }}</button></footer></div></dialog>
</section>
</template>
